INSERT INTO public."Ayah" (id, number, "surahNumber", "textOthmani", "textSimple") VALUES
('s62a1', 1, 62, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'بسم ٱلله ٱلرحمن ٱلرحيم يسبح لله ما في ٱلسموت وما في ٱلارض ٱلملك ٱلقدوس ٱلعزيز ٱلحكيم'),
('s62a2', 2, 62, 'هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّۦنَ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍۢ مُّبِينٍۢ', 'هو ٱلذي بعث في ٱلاميۦن رسولۭا منهم يتلوا۟ عليهم ءايتهۦ ويزكيهم ويعلمهم ٱلكتب وٱلحكمه وان كانوا۟ من قبل لفي ضللۢ مبينۢ'),
('s62a3', 3, 62, 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'وءاخرين منهم لما يلحقوا۟ بهم ۚ وهو ٱلعزيز ٱلحكيم'),
('s62a4', 4, 62, 'ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'ذلك فضل ٱلله يوتيه من يشاء ۚ وٱلله ذو ٱلفضل ٱلعظيم'),
('s62a5', 5, 62, 'مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا ۚ بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'مثل ٱلذين حملوا۟ ٱلتوريه ثم لم يحملوها كمثل ٱلحمار يحمل اسفارۢا ۚ بيس مثل ٱلقوم ٱلذين كذبوا۟ بايت ٱلله ۚ وٱلله لا يهدي ٱلقوم ٱلظلمين'),
('s62a6', 6, 62, 'قُلْ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 'قل يايها ٱلذين هادوا۟ ان زعمتم انكم اولياء لله من دون ٱلناس فتمنوا۟ ٱلموت ان كنتم صدقين'),
('s62a7', 7, 62, 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۚ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'ولا يتمنونهۥ ابدۢا بما قدمت ايديهم ۚ وٱلله عليمۢ بٱلظلمين'),
('s62a8', 8, 62, 'قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَٰقِيكُمْ ۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'قل ان ٱلموت ٱلذي تفرون منه فانهۥ ملقيكم ۖ ثم تردون الي علم ٱلغيب وٱلشهده فينبيكم بما كنتم تعملون'),
('s62a9', 9, 62, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'يايها ٱلذين ءامنوا۟ اذا نودي للصلوه من يوم ٱلجمعه فٱسعوا۟ الي ذكر ٱلله وذروا۟ ٱلبيع ۚ ذلكم خيرۭ لكم ان كنتم تعلمون'),
('s62a10', 10, 62, 'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًۭا لَّعَلَّكُمْ تُفْلِحُونَ', 'فاذا قضيت ٱلصلوه فٱنتشروا۟ في ٱلارض وٱبتغوا۟ من فضل ٱلله وٱذكروا۟ ٱلله كثيرۭا لعلكم تفلحون'),
('s62a11', 11, 62, 'وَإِذَا رَأَوْا۟ تِجَٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًۭا ۚ قُلْ مَا عِندَ ٱللَّهِ خَيْرٌۭ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَٰرَةِ ۚ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ', 'واذا راوا۟ تجره او لهوا ٱنفضوا۟ اليها وتركوك قايمۭا ۚ قل ما عند ٱلله خيرۭ من ٱللهو ومن ٱلتجره ۚ وٱلله خير ٱلرزقين'),
('s63a1', 1, 63, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا جَآءَكَ ٱلْمُنَٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ ۗ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَٰفِقِينَ لَكَٰذِبُونَ', 'بسم ٱلله ٱلرحمن ٱلرحيم اذا جاءك ٱلمنفقون قالوا۟ نشهد انك لرسول ٱلله ۗ وٱلله يعلم انك لرسولهۥ وٱلله يشهد ان ٱلمنفقين لكذبون'),
('s63a2', 2, 63, 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةًۭ فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'ٱتخذوا۟ ايمنهم جنهۭ فصدوا۟ عن سبيل ٱلله ۚ انهم ساء ما كانوا۟ يعملون'),
('s63a3', 3, 63, 'ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'ذلك بانهم ءامنوا۟ ثم كفروا۟ فطبع علي قلوبهم فهم لا يفقهون'),
('s63a4', 4, 63, '۞ وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ ۖ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ ۖ كَأَنَّهُمْ خُشُبٌۭ مُّسَنَّدَةٌۭ ۖ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ ۚ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ ۚ قَٰتَلَهُمُ ٱللَّهُ ۖ أَنَّىٰ يُؤْفَكُونَ', '۞ واذا رايتهم تعجبك اجسامهم ۖ وان يقولوا۟ تسمع لقولهم ۖ كانهم خشبۭ مسندهۭ ۖ يحسبون كل صيحه عليهم ۚ هم ٱلعدو فٱحذرهم ۚ قتلهم ٱلله ۖ اني يوفكون'),
('s63a5', 5, 63, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ', 'واذا قيل لهم تعالوا۟ يستغفر لكم رسول ٱلله لووا۟ رءوسهم ورايتهم يصدون وهم مستكبرون'),
('s63a6', 6, 63, 'سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'سواء عليهم استغفرت لهم ام لم تستغفر لهم لن يغفر ٱلله لهم ۚ ان ٱلله لا يهدي ٱلقوم ٱلفسقين'),
('s63a7', 7, 63, 'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ ۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَفْقَهُونَ', 'هم ٱلذين يقولون لا تنفقوا۟ علي من عند رسول ٱلله حتي ينفضوا۟ ۗ ولله خزاين ٱلسموت وٱلارض ولكن ٱلمنفقين لا يفقهون'),
('s63a8', 8, 63, 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ ۚ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَعْلَمُونَ', 'يقولون لين رجعنا الي ٱلمدينه ليخرجن ٱلاعز منها ٱلاذل ۚ ولله ٱلعزه ولرسولهۦ وللمومنين ولكن ٱلمنفقين لا يعلمون'),
('s63a9', 9, 63, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُمْ عَن ذِكْرِ ٱللَّهِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'يايها ٱلذين ءامنوا۟ لا تلهكم امولكم ولا اولدكم عن ذكر ٱلله ۚ ومن يفعل ذلك فاو۟ليك هم ٱلخسرون'),
('s63a10', 10, 63, 'وَأَنفِقُوا۟ مِن مَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍۢ قَرِيبٍۢ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ', 'وانفقوا۟ من ما رزقنكم من قبل ان ياتي احدكم ٱلموت فيقول رب لولا اخرتني الي اجلۢ قريبۢ فاصدق واكن من ٱلصلحين'),
('s63a11', 11, 63, 'وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'ولن يوخر ٱلله نفسا اذا جاء اجلها ۚ وٱلله خبيرۢ بما تعملون'),
('s64a1', 1, 64, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'بسم ٱلله ٱلرحمن ٱلرحيم يسبح لله ما في ٱلسموت وما في ٱلارض ۖ له ٱلملك وله ٱلحمد ۖ وهو علي كل شيءۢ قدير'),
('s64a2', 2, 64, 'هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌۭ وَمِنكُم مُّؤْمِنٌۭ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'هو ٱلذي خلقكم فمنكم كافرۭ ومنكم مومنۭ ۚ وٱلله بما تعملون بصير'),
('s64a3', 3, 64, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 'خلق ٱلسموت وٱلارض بٱلحق وصوركم فاحسن صوركم ۖ واليه ٱلمصير'),
('s64a4', 4, 64, 'يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ ۚ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'يعلم ما في ٱلسموت وٱلارض ويعلم ما تسرون وما تعلنون ۚ وٱلله عليمۢ بذات ٱلصدور'),
('s64a5', 5, 64, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 'الم ياتكم نبوا۟ ٱلذين كفروا۟ من قبل فذاقوا۟ وبال امرهم ولهم عذاب اليمۭ'),
('s64a6', 6, 64, 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَقَالُوٓا۟ أَبَشَرٌۭ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ ۚ وَّٱسْتَغْنَى ٱللَّهُ ۚ وَٱللَّهُ غَنِىٌّ حَمِيدٌۭ', 'ذلك بانهۥ كانت تاتيهم رسلهم بٱلبينت فقالوا۟ ابشرۭ يهدوننا فكفروا۟ وتولوا۟ ۚ وٱستغني ٱلله ۚ وٱلله غني حميدۭ'),
('s64a7', 7, 64, 'زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ ۚ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ ۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ', 'زعم ٱلذين كفروا۟ ان لن يبعثوا۟ ۚ قل بلي وربي لتبعثن ثم لتنبون بما عملتم ۚ وذلك علي ٱلله يسيرۭ'),
('s64a8', 8, 64, 'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 'فامنوا۟ بٱلله ورسولهۦ وٱلنور ٱلذي انزلنا ۚ وٱلله بما تعملون خبيرۭ'),
('s64a9', 9, 64, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ۖ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًۭا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'يوم يجمعكم ليوم ٱلجمع ۖ ذلك يوم ٱلتغابن ۗ ومن يومنۢ بٱلله ويعمل صلحۭا يكفر عنه سياتهۦ ويدخله جنتۢ تجري من تحتها ٱلانهر خلدين فيها ابدۭا ۚ ذلك ٱلفوز ٱلعظيم'),
('s64a10', 10, 64, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَا ۖ وَبِئْسَ ٱلْمَصِيرُ', 'وٱلذين كفروا۟ وكذبوا۟ بايتنا او۟ليك اصحب ٱلنار خلدين فيها ۖ وبيس ٱلمصير'),
('s64a11', 11, 64, 'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 'ما اصاب من مصيبه الا باذن ٱلله ۗ ومن يومنۢ بٱلله يهد قلبهۥ ۚ وٱلله بكل شيء عليمۭ'),
('s64a12', 12, 64, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۚ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'واطيعوا۟ ٱلله واطيعوا۟ ٱلرسول ۚ فان توليتم فانما علي رسولنا ٱلبلغ ٱلمبين'),
('s64a13', 13, 64, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'ٱلله لا اله الا هو ۚ وعلي ٱلله فليتوكل ٱلمومنون'),
('s64a14', 14, 64, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَٰدِكُمْ عَدُوًّۭا لَّكُمْ فَٱحْذَرُوهُمْ ۚ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 'يايها ٱلذين ءامنوا۟ ان من ازوجكم واولدكم عدوۭا لكم فٱحذروهم ۚ وان تعفوا۟ وتصفحوا۟ وتغفروا۟ فان ٱلله غفورۭ رحيم'),
('s64a15', 15, 64, 'إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌۭ ۚ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌۭ', 'انما امولكم واولدكم فتنهۭ ۚ وٱلله عندهۥ اجر عظيمۭ'),
('s64a16', 16, 64, 'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًۭا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'فٱتقوا۟ ٱلله ما ٱستطعتم وٱسمعوا۟ واطيعوا۟ وانفقوا۟ خيرۭا لانفسكم ۗ ومن يوق شح نفسهۦ فاو۟ليك هم ٱلمفلحون'),
('s64a17', 17, 64, 'إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًۭا يُضَٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ', 'ان تقرضوا۟ ٱلله قرضا حسنۭا يضعفه لكم ويغفر لكم ۚ وٱلله شكور حليم'),
('s64a18', 18, 64, 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'علم ٱلغيب وٱلشهده ٱلعزيز ٱلحكيم'),
('s65a1', 1, 65, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ ۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ ۖ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍۢ مُّبَيِّنَةٍۢ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًۭا', 'بسم ٱلله ٱلرحمن ٱلرحيم يايها ٱلنبي اذا طلقتم ٱلنساء فطلقوهن لعدتهن واحصوا۟ ٱلعده ۖ وٱتقوا۟ ٱلله ربكم ۖ لا تخرجوهن منۢ بيوتهن ولا يخرجن الا ان ياتين بفحشهۢ مبينهۢ ۚ وتلك حدود ٱلله ۚ ومن يتعد حدود ٱلله فقد ظلم نفسهۥ ۚ لا تدري لعل ٱلله يحدث بعد ذلك امرۭا'),
('s65a2', 2, 65, 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍۢ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍۢ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَٰدَةَ لِلَّهِ ۚ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًۭا', 'فاذا بلغن اجلهن فامسكوهن بمعروف او فارقوهن بمعروفۢ واشهدوا۟ ذوي عدلۢ منكم واقيموا۟ ٱلشهده لله ۚ ذلكم يوعظ بهۦ من كان يومن بٱلله وٱليوم ٱلءاخر ۚ ومن يتق ٱلله يجعل لهۥ مخرجۭا'),
('s65a3', 3, 65, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ ۚ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ ۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمْرِهِۦ ۚ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍۢ قَدْرًۭا', 'ويرزقه من حيث لا يحتسب ۚ ومن يتوكل علي ٱلله فهو حسبهۥ ۚ ان ٱلله بلغ امرهۦ ۚ قد جعل ٱلله لكل شيءۢ قدرۭا'),
('s65a4', 4, 65, 'وَٱلَّٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشْهُرٍۢ وَٱلَّٰٓـِٔى لَمْ يَحِضْنَ ۚ وَأُو۟لَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًۭا', 'وٱلي ييسن من ٱلمحيض من نسايكم ان ٱرتبتم فعدتهن ثلثه اشهرۢ وٱلي لم يحضن ۚ واو۟لت ٱلاحمال اجلهن ان يضعن حملهن ۚ ومن يتق ٱلله يجعل لهۥ من امرهۦ يسرۭا'),
('s65a5', 5, 65, 'ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ ۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا', 'ذلك امر ٱلله انزلهۥ اليكم ۚ ومن يتق ٱلله يكفر عنه سياتهۦ ويعظم لهۥ اجرا'),
('s65a6', 6, 65, 'أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ ۚ وَإِن كُنَّ أُو۟لَٰتِ حَمْلٍۢ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ ۚ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ ۖ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍۢ ۖ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ', 'اسكنوهن من حيث سكنتم من وجدكم ولا تضاروهن لتضيقوا۟ عليهن ۚ وان كن او۟لت حملۢ فانفقوا۟ عليهن حتي يضعن حملهن ۚ فان ارضعن لكم فاتوهن اجورهن ۖ واتمروا۟ بينكم بمعروفۢ ۖ وان تعاسرتم فسترضع لهۥ اخري'),
('s65a7', 7, 65, 'لِيُنفِقْ ذُو سَعَةٍۢ مِّن سَعَتِهِۦ ۖ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ ۚ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا ۚ سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍۢ يُسْرًۭا', 'لينفق ذو سعهۢ من سعتهۦ ۖ ومن قدر عليه رزقهۥ فلينفق مما ءاتيه ٱلله ۚ لا يكلف ٱلله نفسا الا ما ءاتيها ۚ سيجعل ٱلله بعد عسرۢ يسرۭا'),
('s65a8', 8, 65, 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَٰهَا حِسَابًۭا شَدِيدًۭا وَعَذَّبْنَٰهَا عَذَابًۭا نُّكْرًۭا', 'وكاين من قريه عتت عن امر ربها ورسلهۦ فحاسبنها حسابۭا شديدۭا وعذبنها عذابۭا نكرۭا'),
('s65a9', 9, 65, 'فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَٰقِبَةُ أَمْرِهَا خُسْرًا', 'فذاقت وبال امرها وكان عقبه امرها خسرا'),
('s65a10', 10, 65, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًۭا شَدِيدًۭا ۖ فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ ٱلَّذِينَ ءَامَنُوا۟ ۚ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًۭا', 'اعد ٱلله لهم عذابۭا شديدۭا ۖ فٱتقوا۟ ٱلله ياو۟لي ٱلالبب ٱلذين ءامنوا۟ ۚ قد انزل ٱلله اليكم ذكرۭا'),
('s65a11', 11, 65, 'رَّسُولًۭا يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٍۢ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ ۚ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًۭا يُدْخِلْهُ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا', 'رسولۭا يتلوا۟ عليكم ءايت ٱلله مبينتۢ ليخرج ٱلذين ءامنوا۟ وعملوا۟ ٱلصلحت من ٱلظلمت الي ٱلنور ۚ ومن يومنۢ بٱلله ويعمل صلحۭا يدخله جنتۢ تجري من تحتها ٱلانهر خلدين فيها ابدۭا ۖ قد احسن ٱلله لهۥ رزقا'),
('s65a12', 12, 65, 'ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍۢ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا', 'ٱلله ٱلذي خلق سبع سموتۢ ومن ٱلارض مثلهن يتنزل ٱلامر بينهن لتعلموا۟ ان ٱلله علي كل شيءۢ قديرۭ وان ٱلله قد احاط بكل شيء علمۢا'),
('s66a1', 1, 66, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ ۖ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 'بسم ٱلله ٱلرحمن ٱلرحيم يايها ٱلنبي لم تحرم ما احل ٱلله لك ۖ تبتغي مرضات ازوجك ۚ وٱلله غفورۭ رحيمۭ'),
('s66a2', 2, 66, 'قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَٰنِكُمْ ۚ وَٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'قد فرض ٱلله لكم تحله ايمنكم ۚ وٱلله موليكم ۖ وهو ٱلعليم ٱلحكيم'),
('s66a3', 3, 66, 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًۭا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍۢ ۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَٰذَا ۖ قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ', 'واذ اسر ٱلنبي الي بعض ازوجهۦ حديثۭا فلما نبات بهۦ واظهره ٱلله عليه عرف بعضهۥ واعرض عنۢ بعضۢ ۖ فلما نباها بهۦ قالت من انۢباك هذا ۖ قال نباني ٱلعليم ٱلخبير'),
('s66a4', 4, 66, 'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ۖ وَإِن تَظَٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَٰلِحُ ٱلْمُؤْمِنِينَ ۖ وَٱلْمَلَٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ', 'ان تتوبا الي ٱلله فقد صغت قلوبكما ۖ وان تظهرا عليه فان ٱلله هو موليه وجبريل وصلح ٱلمومنين ۖ وٱلمليكه بعد ذلك ظهير'),
('s66a5', 5, 66, 'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًۭا مِّنكُنَّ مُسْلِمَٰتٍۢ مُّؤْمِنَٰتٍۢ قَٰنِتَٰتٍۢ تَٰٓئِبَٰتٍ عَٰبِدَٰتٍۢ سَٰٓئِحَٰتٍۢ ثَيِّبَٰتٍۢ وَأَبْكَارًۭا', 'عسي ربهۥ ان طلقكن ان يبدلهۥ ازوجا خيرۭا منكن مسلمتۢ مومنتۢ قنتتۢ تيبت عبدتۢ سيحتۢ ثيبتۢ وابكارۭا'),
('s66a6', 6, 66, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًۭا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَاظٌۭ شِدَادٌۭ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 'يايها ٱلذين ءامنوا۟ قوا۟ انفسكم واهليكم نارۭا وقودها ٱلناس وٱلحجاره عليها مليكه غلاظۭ شدادۭ لا يعصون ٱلله ما امرهم ويفعلون ما يومرون'),
('s66a7', 7, 66, 'يَٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'يايها ٱلذين كفروا۟ لا تعتذروا۟ ٱليوم ۖ انما تجزون ما كنتم تعملون'),
('s66a8', 8, 66, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةًۭ نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ ۖ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 'يايها ٱلذين ءامنوا۟ توبوا۟ الي ٱلله توبهۭ نصوحا عسي ربكم ان يكفر عنكم سياتكم ويدخلكم جنتۢ تجري من تحتها ٱلانهر يوم لا يخزي ٱلله ٱلنبي وٱلذين ءامنوا۟ معهۥ ۖ نورهم يسعي بين ايديهم وبايمنهم يقولون ربنا اتمم لنا نورنا وٱغفر لنا ۖ انك علي كل شيءۢ قديرۭ'),
('s66a9', 9, 66, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'يايها ٱلنبي جهد ٱلكفار وٱلمنفقين وٱغلظ عليهم ۚ وماويهم جهنم ۖ وبيس ٱلمصير'),
('s66a10', 10, 66, 'ضَرَبَ ٱللَّهُ مَثَلًۭا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍۢ وَٱمْرَأَتَ لُوطٍۢ ۖ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًۭٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ', 'ضرب ٱلله مثلۭا للذين كفروا۟ ٱمرات نوحۢ وٱمرات لوطۢ ۖ كانتا تحت عبدين من عبادنا صلحين فخانتاهما فلم يغنيا عنهما من ٱلله شيۭا وقيل ٱدخلا ٱلنار مع ٱلدخلين'),
('s66a11', 11, 66, 'وَضَرَبَ ٱللَّهُ مَثَلًۭا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًۭا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'وضرب ٱلله مثلۭا للذين ءامنوا۟ ٱمرات فرعون اذ قالت رب ٱبن لي عندك بيتۭا في ٱلجنه ونجني من فرعون وعملهۦ ونجني من ٱلقوم ٱلظلمين'),
('s66a12', 12, 66, 'وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَٰنِتِينَ', 'ومريم ٱبنت عمرن ٱلتي احصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمت ربها وكتبهۦ وكانت من ٱلقنتين'),
('s67a1', 1, 67, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 'بسم ٱلله ٱلرحمن ٱلرحيم تبرك ٱلذي بيده ٱلملك وهو علي كل شيءۢ قدير'),
('s67a2', 2, 67, 'ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ', 'ٱلذي خلق ٱلموت وٱلحيوه ليبلوكم ايكم احسن عملۭا ۚ وهو ٱلعزيز ٱلغفور'),
('s67a3', 3, 67, 'ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍۢ طِبَاقًۭا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ مِن تَفَٰوُتٍۢ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍۢ', 'ٱلذي خلق سبع سموتۢ طباقۭا ۖ ما تري في خلق ٱلرحمن من تفوتۢ ۖ فٱرجع ٱلبصر هل تري من فطورۢ'),
('s67a4', 4, 67, 'ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًۭا وَهُوَ حَسِيرٌۭ', 'ثم ٱرجع ٱلبصر كرتين ينقلب اليك ٱلبصر خاسيۭا وهو حسيرۭ'),
('s67a5', 5, 67, 'وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُومًۭا لِّلشَّيَٰطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ', 'ولقد زينا ٱلسماء ٱلدنيا بمصبيح وجعلنها رجومۭا للشيطين ۖ واعتدنا لهم عذاب ٱلسعير'),
('s67a6', 6, 67, 'وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ ٱلْمَصِيرُ', 'وللذين كفروا۟ بربهم عذاب جهنم ۖ وبيس ٱلمصير'),
('s67a7', 7, 67, 'إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًۭا وَهِىَ تَفُورُ', 'اذا القوا۟ فيها سمعوا۟ لها شهيقۭا وهي تفور'),
('s67a8', 8, 67, 'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ ۖ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌۭ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌۭ', 'تكاد تميز من ٱلغيظ ۖ كلما القي فيها فوجۭ سالهم خزنتها الم ياتكم نذيرۭ'),
('s67a9', 9, 67, 'قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌۭ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍۢ كَبِيرٍۢ', 'قالوا۟ بلي قد جاءنا نذيرۭ فكذبنا وقلنا ما نزل ٱلله من شيء ان انتم الا في ضللۢ كبيرۢ'),
('s67a10', 10, 67, 'وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَٰبِ ٱلسَّعِيرِ', 'وقالوا۟ لو كنا نسمع او نعقل ما كنا في اصحب ٱلسعير'),
('s67a11', 11, 67, 'فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًۭا لِّأَصْحَٰبِ ٱلسَّعِيرِ', 'فٱعترفوا۟ بذنۢبهم فسحقۭا لاصحب ٱلسعير'),
('s67a12', 12, 67, 'إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌۭ كَبِيرٌۭ', 'ان ٱلذين يخشون ربهم بٱلغيب لهم مغفرهۭ واجرۭ كبيرۭ'),
('s67a13', 13, 67, 'وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ ۖ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'واسروا۟ قولكم او ٱجهروا۟ بهۦ ۖ انهۥ عليمۢ بذات ٱلصدور'),
('s67a14', 14, 67, 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'الا يعلم من خلق وهو ٱللطيف ٱلخبير'),
('s67a15', 15, 67, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًۭا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ ۖ وَإِلَيْهِ ٱلنُّشُورُ', 'هو ٱلذي جعل لكم ٱلارض ذلولۭا فٱمشوا۟ في مناكبها وكلوا۟ من رزقهۦ ۖ واليه ٱلنشور'),
('s67a16', 16, 67, 'ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ', 'ءامنتم من في ٱلسماء ان يخسف بكم ٱلارض فاذا هي تمور'),
('s67a17', 17, 67, 'أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًۭا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ', 'ام امنتم من في ٱلسماء ان يرسل عليكم حاصبۭا ۖ فستعلمون كيف نذير'),
('s67a18', 18, 67, 'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ', 'ولقد كذب ٱلذين من قبلهم فكيف كان نكير'),
('s67a19', 19, 67, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتٍۢ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَٰنُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ', 'اولم يروا۟ الي ٱلطير فوقهم صفتۢ ويقبضن ۚ ما يمسكهن الا ٱلرحمن ۚ انهۥ بكل شيءۭ بصير'),
('s67a20', 20, 67, 'أَمَّنْ هَٰذَا ٱلَّذِى هُوَ جُندٌۭ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَٰنِ ۚ إِنِ ٱلْكَٰفِرُونَ إِلَّا فِى غُرُورٍ', 'امن هذا ٱلذي هو جندۭ لكم ينصركم من دون ٱلرحمن ۚ ان ٱلكفرون الا في غرور'),
('s67a21', 21, 67, 'أَمَّنْ هَٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ ۚ بَل لَّجُّوا۟ فِى عُتُوٍّۢ وَنُفُورٍ', 'امن هذا ٱلذي يرزقكم ان امسك رزقهۥ ۚ بل لجوا۟ في عتوۢ ونفور'),
('s67a22', 22, 67, 'أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 'افمن يمشي مكبا علي وجههۦ اهدي امن يمشي سويا علي صرطۢ مستقيمۢ'),
('s67a23', 23, 67, 'قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۖ قَلِيلًۭا مَّا تَشْكُرُونَ', 'قل هو ٱلذي انشاكم وجعل لكم ٱلسمع وٱلابصر وٱلافده ۖ قليلۭا ما تشكرون'),
('s67a24', 24, 67, 'قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 'قل هو ٱلذي ذراكم في ٱلارض واليه تحشرون'),
('s67a25', 25, 67, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 'ويقولون متي هذا ٱلوعد ان كنتم صدقين'),
('s67a26', 26, 67, 'قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌۭ مُّبِينٌۭ', 'قل انما ٱلعلم عند ٱلله وانما انا۠ نذيرۭ مبينۭ'),
('s67a27', 27, 67, 'فَلَمَّا رَأَوْهُ زُلْفَةًۭ سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ', 'فلما راوه زلفهۭ سيت وجوه ٱلذين كفروا۟ وقيل هذا ٱلذي كنتم بهۦ تدعون'),
('s67a28', 28, 67, 'قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍۢ', 'قل ارءيتم ان اهلكني ٱلله ومن معي او رحمنا فمن يجير ٱلكفرين من عذاب اليمۢ'),
('s67a29', 29, 67, 'قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 'قل هو ٱلرحمن ءامنا بهۦ وعليه توكلنا ۖ فستعلمون من هو في ضللۢ مبينۢ'),
('s67a30', 30, 67, 'قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًۭا فَمَن يَأْتِيكُم بِمَآءٍۢ مَّعِينٍۭ', 'قل ارءيتم ان اصبح ماوكم غورۭا فمن ياتيكم بماءۢ معينۭ'),
('s68a1', 1, 68, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ نٓ ۚ وَٱلْقَلَمِ وَمَا يَسْطُرُونَ', 'بسم ٱلله ٱلرحمن ٱلرحيم ن ۚ وٱلقلم وما يسطرون'),
('s68a2', 2, 68, 'مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍۢ', 'ما انت بنعمه ربك بمجنونۢ'),
('s68a3', 3, 68, 'وَإِنَّ لَكَ لَأَجْرًا غَيْرَ مَمْنُونٍۢ', 'وان لك لاجرا غير ممنونۢ'),
('s68a4', 4, 68, 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍۢ', 'وانك لعلي خلق عظيمۢ'),
('s68a5', 5, 68, 'فَسَتُبْصِرُ وَيُبْصِرُونَ', 'فستبصر ويبصرون'),
('s68a6', 6, 68, 'بِأَييِّكُمُ ٱلْمَفْتُونُ', 'باييكم ٱلمفتون'),
('s68a7', 7, 68, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'ان ربك هو اعلم بمن ضل عن سبيلهۦ وهو اعلم بٱلمهتدين'),
('s68a8', 8, 68, 'فَلَا تُطِعِ ٱلْمُكَذِّبِينَ', 'فلا تطع ٱلمكذبين'),
('s68a9', 9, 68, 'وَدُّوا۟ لَوْ تُدْهِنُ فَيُدْهِنُونَ', 'ودوا۟ لو تدهن فيدهنون'),
('s68a10', 10, 68, 'وَلَا تُطِعْ كُلَّ حَلَّافٍۢ مَّهِينٍ', 'ولا تطع كل حلافۢ مهين'),
('s68a11', 11, 68, 'هَمَّازٍۢ مَّشَّآءٍۭ بِنَمِيمٍۢ', 'همازۢ مشاءۭ بنميمۢ'),
('s68a12', 12, 68, 'مَّنَّاعٍۢ لِّلْخَيْرِ مُعْتَدٍ أَثِيمٍ', 'مناعۢ للخير معتد اثيم'),
('s68a13', 13, 68, 'عُتُلٍّۭ بَعْدَ ذَٰلِكَ زَنِيمٍ', 'عتلۭ بعد ذلك زنيم'),
('s68a14', 14, 68, 'أَن كَانَ ذَا مَالٍۢ وَبَنِينَ', 'ان كان ذا مالۢ وبنين'),
('s68a15', 15, 68, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'اذا تتلي عليه ءايتنا قال اسطير ٱلاولين'),
('s68a16', 16, 68, 'سَنَسِمُهُۥ عَلَى ٱلْخُرْطُومِ', 'سنسمهۥ علي ٱلخرطوم'),
('s68a17', 17, 68, 'إِنَّا بَلَوْنَٰهُمْ كَمَا بَلَوْنَآ أَصْحَٰبَ ٱلْجَنَّةِ إِذْ أَقْسَمُوا۟ لَيَصْرِمُنَّهَا مُصْبِحِينَ', 'انا بلونهم كما بلونا اصحب ٱلجنه اذ اقسموا۟ ليصرمنها مصبحين'),
('s68a18', 18, 68, 'وَلَا يَسْتَثْنُونَ', 'ولا يستثنون'),
('s68a19', 19, 68, 'فَطَافَ عَلَيْهَا طَآئِفٌۭ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ', 'فطاف عليها طايفۭ من ربك وهم نايمون'),
('s68a20', 20, 68, 'فَأَصْبَحَتْ كَٱلصَّرِيمِ', 'فاصبحت كٱلصريم'),
('s68a21', 21, 68, 'فَتَنَادَوْا۟ مُصْبِحِينَ', 'فتنادوا۟ مصبحين'),
('s68a22', 22, 68, 'أَنِ ٱغْدُوا۟ عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَٰرِمِينَ', 'ان ٱغدوا۟ علي حرثكم ان كنتم صرمين'),
('s68a23', 23, 68, 'فَٱنطَلَقُوا۟ وَهُمْ يَتَخَٰفَتُونَ', 'فٱنطلقوا۟ وهم يتخفتون'),
('s68a24', 24, 68, 'أَن لَّا يَدْخُلَنَّهَا ٱلْيَوْمَ عَلَيْكُم مِّسْكِينٌۭ', 'ان لا يدخلنها ٱليوم عليكم مسكينۭ'),
('s68a25', 25, 68, 'وَغَدَوْا۟ عَلَىٰ حَرْدٍۢ قَٰدِرِينَ', 'وغدوا۟ علي حردۢ قدرين'),
('s68a26', 26, 68, 'فَلَمَّا رَأَوْهَا قَالُوٓا۟ إِنَّا لَضَآلُّونَ', 'فلما راوها قالوا۟ انا لضالون'),
('s68a27', 27, 68, 'بَلْ نَحْنُ مَحْرُومُونَ', 'بل نحن محرومون'),
('s68a28', 28, 68, 'قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ', 'قال اوسطهم الم اقل لكم لولا تسبحون'),
('s68a29', 29, 68, 'قَالُوا۟ سُبْحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'قالوا۟ سبحن ربنا انا كنا ظلمين'),
('s68a30', 30, 68, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَلَٰوَمُونَ', 'فاقبل بعضهم علي بعضۢ يتلومون'),
('s68a31', 31, 68, 'قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا طَٰغِينَ', 'قالوا۟ يويلنا انا كنا طغين'),
('s68a32', 32, 68, 'عَسَىٰ رَبُّنَآ أَن يُبْدِلَنَا خَيْرًۭا مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ', 'عسي ربنا ان يبدلنا خيرۭا منها انا الي ربنا رغبون'),
('s68a33', 33, 68, 'كَذَٰلِكَ ٱلْعَذَابُ ۖ وَلَعَذَابُ ٱلْءَاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 'كذلك ٱلعذاب ۖ ولعذاب ٱلءاخره اكبر ۚ لو كانوا۟ يعلمون'),
('s68a34', 34, 68, 'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّٰتِ ٱلنَّعِيمِ', 'ان للمتقين عند ربهم جنت ٱلنعيم'),
('s68a35', 35, 68, 'أَفَنَجْعَلُ ٱلْمُسْلِمِينَ كَٱلْمُجْرِمِينَ', 'افنجعل ٱلمسلمين كٱلمجرمين'),
('s68a36', 36, 68, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', 'ما لكم كيف تحكمون'),
('s68a37', 37, 68, 'أَمْ لَكُمْ كِتَٰبٌۭ فِيهِ تَدْرُسُونَ', 'ام لكم كتبۭ فيه تدرسون'),
('s68a38', 38, 68, 'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ', 'ان لكم فيه لما تخيرون'),
('s68a39', 39, 68, 'أَمْ لَكُمْ أَيْمَٰنٌ عَلَيْنَا بَٰلِغَةٌ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۙ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ', 'ام لكم ايمن علينا بلغه الي يوم ٱلقيمه ۙ ان لكم لما تحكمون'),
('s68a40', 40, 68, 'سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ', 'سلهم ايهم بذلك زعيم'),
('s68a41', 41, 68, 'أَمْ لَهُمْ شُرَكَآءُ فَلْيَأْتُوا۟ بِشُرَكَآئِهِمْ إِن كَانُوا۟ صَٰدِقِينَ', 'ام لهم شركاء فلياتوا۟ بشركايهم ان كانوا۟ صدقين'),
('s68a42', 42, 68, 'يَوْمَ يُكْشَفُ عَن سَاقٍۢ وَيُدْعَوْنَ إِلَى ٱلسُّجُودِ فَلَا يَسْتَطِيعُونَ', 'يوم يكشف عن ساقۢ ويدعون الي ٱلسجود فلا يستطيعون'),
('s68a43', 43, 68, 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌۭ ۖ وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَٰلِمُونَ', 'خشعه ابصرهم ترهقهم ذلهۭ ۖ وقد كانوا۟ يدعون الي ٱلسجود وهم سلمون'),
('s68a44', 44, 68, 'فَذَرْنِى وَمَن يُكَذِّبُ بِهَٰذَا ٱلْحَدِيثِ ۖ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 'فذرني ومن يكذب بهذا ٱلحديث ۖ سنستدرجهم من حيث لا يعلمون'),
('s68a45', 45, 68, 'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ', 'واملي لهم ۚ ان كيدي متين'),
('s68a46', 46, 68, 'أَمْ تَسْـَٔلُهُمْ أَجْرًۭا فَهُم مِّن مَّغْرَمٍۢ مُّثْقَلُونَ', 'ام تسلهم اجرۭا فهم من مغرمۢ مثقلون'),
('s68a47', 47, 68, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', 'ام عندهم ٱلغيب فهم يكتبون'),
('s68a48', 48, 68, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌۭ', 'فٱصبر لحكم ربك ولا تكن كصاحب ٱلحوت اذ نادي وهو مكظومۭ'),
('s68a49', 49, 68, 'لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةٌۭ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلْعَرَآءِ وَهُوَ مَذْمُومٌۭ', 'لولا ان تدركهۥ نعمهۭ من ربهۦ لنبذ بٱلعراء وهو مذمومۭ'),
('s68a50', 50, 68, 'فَٱجْتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ', 'فٱجتبه ربهۥ فجعلهۥ من ٱلصلحين'),
('s68a51', 51, 68, 'وَإِن يَكَادُ ٱلَّذِينَ كَفَرُوا۟ لَيُزْلِقُونَكَ بِأَبْصَٰرِهِمْ لَمَّا سَمِعُوا۟ ٱلذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونٌۭ', 'وان يكاد ٱلذين كفروا۟ ليزلقونك بابصرهم لما سمعوا۟ ٱلذكر ويقولون انهۥ لمجنونۭ'),
('s68a52', 52, 68, 'وَمَا هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ', 'وما هو الا ذكرۭ للعلمين'),
('s69a1', 1, 69, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَآقَّةُ', 'بسم ٱلله ٱلرحمن ٱلرحيم ٱلحاقه'),
('s69a2', 2, 69, 'مَا ٱلْحَآقَّةُ', 'ما ٱلحاقه'),
('s69a3', 3, 69, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحَآقَّةُ', 'وما ادريك ما ٱلحاقه'),
('s69a4', 4, 69, 'كَذَّبَتْ ثَمُودُ وَعَادٌۢ بِٱلْقَارِعَةِ', 'كذبت ثمود وعادۢ بٱلقارعه'),
('s69a5', 5, 69, 'فَأَمَّا ثَمُودُ فَأُهْلِكُوا۟ بِٱلطَّاغِيَةِ', 'فاما ثمود فاهلكوا۟ بٱلطاغيه'),
('s69a6', 6, 69, 'وَأَمَّا عَادٌۭ فَأُهْلِكُوا۟ بِرِيحٍۢ صَرْصَرٍ عَاتِيَةٍۢ', 'واما عادۭ فاهلكوا۟ بريحۢ صرصر عاتيهۢ'),
('s69a7', 7, 69, 'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍۢ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومًۭا فَتَرَى ٱلْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍۢ', 'سخرها عليهم سبع ليالۢ وثمنيه ايام حسومۭا فتري ٱلقوم فيها صرعي كانهم اعجاز نخل خاويهۢ'),
('s69a8', 8, 69, 'فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٍۢ', 'فهل تري لهم منۢ باقيهۢ'),
('s69a9', 9, 69, 'وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَٱلْمُؤْتَفِكَٰتُ بِٱلْخَاطِئَةِ', 'وجاء فرعون ومن قبلهۥ وٱلموتفكت بٱلخاطيه'),
('s69a10', 10, 69, 'فَعَصَوْا۟ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةًۭ رَّابِيَةً', 'فعصوا۟ رسول ربهم فاخذهم اخذهۭ رابيه'),
('s69a11', 11, 69, 'إِنَّا لَمَّا طَغَا ٱلْمَآءُ حَمَلْنَٰكُمْ فِى ٱلْجَارِيَةِ', 'انا لما طغا ٱلماء حملنكم في ٱلجاريه'),
('s69a12', 12, 69, 'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةًۭ وَتَعِيَهَآ أُذُنٌۭ وَٰعِيَةٌۭ', 'لنجعلها لكم تذكرهۭ وتعيها اذنۭ وعيهۭ'),
('s69a13', 13, 69, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ نَفْخَةٌۭ وَٰحِدَةٌۭ', 'فاذا نفخ في ٱلصور نفخهۭ وحدهۭ'),
('s69a14', 14, 69, 'وَحُمِلَتِ ٱلْأَرْضُ وَٱلْجِبَالُ فَدُكَّتَا دَكَّةًۭ وَٰحِدَةًۭ', 'وحملت ٱلارض وٱلجبال فدكتا دكهۭ وحدهۭ'),
('s69a15', 15, 69, 'فَيَوْمَئِذٍۢ وَقَعَتِ ٱلْوَاقِعَةُ', 'فيوميذۢ وقعت ٱلواقعه'),
('s69a16', 16, 69, 'وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِىَ يَوْمَئِذٍۢ وَاهِيَةٌۭ', 'وٱنشقت ٱلسماء فهي يوميذۢ واهيهۭ'),
('s69a17', 17, 69, 'وَٱلْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا ۚ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍۢ ثَمَٰنِيَةٌۭ', 'وٱلملك علي ارجايها ۚ ويحمل عرش ربك فوقهم يوميذۢ ثمنيهۭ'),
('s69a18', 18, 69, 'يَوْمَئِذٍۢ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٌۭ', 'يوميذۢ تعرضون لا تخفي منكم خافيهۭ'),
('s69a19', 19, 69, 'فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقْرَءُوا۟ كِتَٰبِيَهْ', 'فاما من اوتي كتبهۥ بيمينهۦ فيقول هاوم ٱقرءوا۟ كتبيه'),
('s69a20', 20, 69, 'إِنِّى ظَنَنتُ أَنِّى مُلَٰقٍ حِسَابِيَهْ', 'اني ظننت اني ملق حسابيه'),
('s69a21', 21, 69, 'فَهُوَ فِى عِيشَةٍۢ رَّاضِيَةٍۢ', 'فهو في عيشهۢ راضيهۢ'),
('s69a22', 22, 69, 'فِى جَنَّةٍ عَالِيَةٍۢ', 'في جنه عاليهۢ'),
('s69a23', 23, 69, 'قُطُوفُهَا دَانِيَةٌۭ', 'قطوفها دانيهۭ'),
('s69a24', 24, 69, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَآ أَسْلَفْتُمْ فِى ٱلْأَيَّامِ ٱلْخَالِيَةِ', 'كلوا۟ وٱشربوا۟ هنيۢا بما اسلفتم في ٱلايام ٱلخاليه'),
('s69a25', 25, 69, 'وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيْتَنِى لَمْ أُوتَ كِتَٰبِيَهْ', 'واما من اوتي كتبهۥ بشمالهۦ فيقول يليتني لم اوت كتبيه'),
('s69a26', 26, 69, 'وَلَمْ أَدْرِ مَا حِسَابِيَهْ', 'ولم ادر ما حسابيه'),
('s69a27', 27, 69, 'يَٰلَيْتَهَا كَانَتِ ٱلْقَاضِيَةَ', 'يليتها كانت ٱلقاضيه'),
('s69a28', 28, 69, 'مَآ أَغْنَىٰ عَنِّى مَالِيَهْ ۜ', 'ما اغني عني ماليه ۜ'),
('s69a29', 29, 69, 'هَلَكَ عَنِّى سُلْطَٰنِيَهْ', 'هلك عني سلطنيه'),
('s69a30', 30, 69, 'خُذُوهُ فَغُلُّوهُ', 'خذوه فغلوه'),
('s69a31', 31, 69, 'ثُمَّ ٱلْجَحِيمَ صَلُّوهُ', 'ثم ٱلجحيم صلوه'),
('s69a32', 32, 69, 'ثُمَّ فِى سِلْسِلَةٍۢ ذَرْعُهَا سَبْعُونَ ذِرَاعًۭا فَٱسْلُكُوهُ', 'ثم في سلسلهۢ ذرعها سبعون ذراعۭا فٱسلكوه'),
('s69a33', 33, 69, 'إِنَّهُۥ كَانَ لَا يُؤْمِنُ بِٱللَّهِ ٱلْعَظِيمِ', 'انهۥ كان لا يومن بٱلله ٱلعظيم'),
('s69a34', 34, 69, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'ولا يحض علي طعام ٱلمسكين'),
('s69a35', 35, 69, 'فَلَيْسَ لَهُ ٱلْيَوْمَ هَٰهُنَا حَمِيمٌۭ', 'فليس له ٱليوم ههنا حميمۭ'),
('s69a36', 36, 69, 'وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍۢ', 'ولا طعام الا من غسلينۢ'),
('s69a37', 37, 69, 'لَّا يَأْكُلُهُۥٓ إِلَّا ٱلْخَٰطِـُٔونَ', 'لا ياكلهۥ الا ٱلخطون'),
('s69a38', 38, 69, 'فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ', 'فلا اقسم بما تبصرون'),
('s69a39', 39, 69, 'وَمَا لَا تُبْصِرُونَ', 'وما لا تبصرون'),
('s69a40', 40, 69, 'إِنَّهُۥ لَقَوْلُ رَسُولٍۢ كَرِيمٍۢ', 'انهۥ لقول رسولۢ كريمۢ'),
('s69a41', 41, 69, 'وَمَا هُوَ بِقَوْلِ شَاعِرٍۢ ۚ قَلِيلًۭا مَّا تُؤْمِنُونَ', 'وما هو بقول شاعرۢ ۚ قليلۭا ما تومنون'),
('s69a42', 42, 69, 'وَلَا بِقَوْلِ كَاهِنٍۢ ۚ قَلِيلًۭا مَّا تَذَكَّرُونَ', 'ولا بقول كاهنۢ ۚ قليلۭا ما تذكرون'),
('s69a43', 43, 69, 'تَنزِيلٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'تنزيلۭ من رب ٱلعلمين'),
('s69a44', 44, 69, 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ٱلْأَقَاوِيلِ', 'ولو تقول علينا بعض ٱلاقاويل'),
('s69a45', 45, 69, 'لَأَخَذْنَا مِنْهُ بِٱلْيَمِينِ', 'لاخذنا منه بٱليمين'),
('s69a46', 46, 69, 'ثُمَّ لَقَطَعْنَا مِنْهُ ٱلْوَتِينَ', 'ثم لقطعنا منه ٱلوتين'),
('s69a47', 47, 69, 'فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَٰجِزِينَ', 'فما منكم من احد عنه حجزين'),
('s69a48', 48, 69, 'وَإِنَّهُۥ لَتَذْكِرَةٌۭ لِّلْمُتَّقِينَ', 'وانهۥ لتذكرهۭ للمتقين'),
('s69a49', 49, 69, 'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ', 'وانا لنعلم ان منكم مكذبين'),
('s69a50', 50, 69, 'وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ٱلْكَٰفِرِينَ', 'وانهۥ لحسره علي ٱلكفرين'),
('s69a51', 51, 69, 'وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ', 'وانهۥ لحق ٱليقين'),
('s69a52', 52, 69, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 'فسبح بٱسم ربك ٱلعظيم'),
('s70a1', 1, 70, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَأَلَ سَآئِلٌۢ بِعَذَابٍۢ وَاقِعٍۢ', 'بسم ٱلله ٱلرحمن ٱلرحيم سال سايلۢ بعذابۢ واقعۢ'),
('s70a2', 2, 70, 'لِّلْكَٰفِرِينَ لَيْسَ لَهُۥ دَافِعٌۭ', 'للكفرين ليس لهۥ دافعۭ'),
('s70a3', 3, 70, 'مِّنَ ٱللَّهِ ذِى ٱلْمَعَارِجِ', 'من ٱلله ذي ٱلمعارج'),
('s70a4', 4, 70, 'تَعْرُجُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ إِلَيْهِ فِى يَوْمٍۢ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةٍۢ', 'تعرج ٱلمليكه وٱلروح اليه في يومۢ كان مقدارهۥ خمسين الف سنهۢ'),
('s70a5', 5, 70, 'فَٱصْبِرْ صَبْرًۭا جَمِيلًا', 'فٱصبر صبرۭا جميلا'),
('s70a6', 6, 70, 'إِنَّهُمْ يَرَوْنَهُۥ بَعِيدًۭا', 'انهم يرونهۥ بعيدۭا'),
('s70a7', 7, 70, 'وَنَرَىٰهُ قَرِيبًۭا', 'ونريه قريبۭا'),
('s70a8', 8, 70, 'يَوْمَ تَكُونُ ٱلسَّمَآءُ كَٱلْمُهْلِ', 'يوم تكون ٱلسماء كٱلمهل'),
('s70a9', 9, 70, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ', 'وتكون ٱلجبال كٱلعهن'),
('s70a10', 10, 70, 'وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيمًۭا', 'ولا يسل حميم حميمۭا'),
('s70a11', 11, 70, 'يُبَصَّرُونَهُمْ ۚ يَوَدُّ ٱلْمُجْرِمُ لَوْ يَفْتَدِى مِنْ عَذَابِ يَوْمِئِذٍۭ بِبَنِيهِ', 'يبصرونهم ۚ يود ٱلمجرم لو يفتدي من عذاب يوميذۭ ببنيه'),
('s70a12', 12, 70, 'وَصَٰحِبَتِهِۦ وَأَخِيهِ', 'وصحبتهۦ واخيه'),
('s70a13', 13, 70, 'وَفَصِيلَتِهِ ٱلَّتِى تُـْٔوِيهِ', 'وفصيلته ٱلتي تويه'),
('s70a14', 14, 70, 'وَمَن فِى ٱلْأَرْضِ جَمِيعًۭا ثُمَّ يُنجِيهِ', 'ومن في ٱلارض جميعۭا ثم ينجيه'),
('s70a15', 15, 70, 'كَلَّآ ۖ إِنَّهَا لَظَىٰ', 'كلا ۖ انها لظي'),
('s70a16', 16, 70, 'نَزَّاعَةًۭ لِّلشَّوَىٰ', 'نزاعهۭ للشوي'),
('s70a17', 17, 70, 'تَدْعُوا۟ مَنْ أَدْبَرَ وَتَوَلَّىٰ', 'تدعوا۟ من ادبر وتولي'),
('s70a18', 18, 70, 'وَجَمَعَ فَأَوْعَىٰٓ', 'وجمع فاوعي'),
('s70a19', 19, 70, '۞ إِنَّ ٱلْإِنسَٰنَ خُلِقَ هَلُوعًا', '۞ ان ٱلانسن خلق هلوعا'),
('s70a20', 20, 70, 'إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعًۭا', 'اذا مسه ٱلشر جزوعۭا'),
('s70a21', 21, 70, 'وَإِذَا مَسَّهُ ٱلْخَيْرُ مَنُوعًا', 'واذا مسه ٱلخير منوعا'),
('s70a22', 22, 70, 'إِلَّا ٱلْمُصَلِّينَ', 'الا ٱلمصلين'),
('s70a23', 23, 70, 'ٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ', 'ٱلذين هم علي صلاتهم دايمون'),
('s70a24', 24, 70, 'وَٱلَّذِينَ فِىٓ أَمْوَٰلِهِمْ حَقٌّۭ مَّعْلُومٌۭ', 'وٱلذين في امولهم حقۭ معلومۭ'),
('s70a25', 25, 70, 'لِّلسَّآئِلِ وَٱلْمَحْرُومِ', 'للسايل وٱلمحروم'),
('s70a26', 26, 70, 'وَٱلَّذِينَ يُصَدِّقُونَ بِيَوْمِ ٱلدِّينِ', 'وٱلذين يصدقون بيوم ٱلدين'),
('s70a27', 27, 70, 'وَٱلَّذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ', 'وٱلذين هم من عذاب ربهم مشفقون'),
('s70a28', 28, 70, 'إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍۢ', 'ان عذاب ربهم غير مامونۢ'),
('s70a29', 29, 70, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ', 'وٱلذين هم لفروجهم حفظون'),
('s70a30', 30, 70, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', 'الا علي ازوجهم او ما ملكت ايمنهم فانهم غير ملومين'),
('s70a31', 31, 70, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْعَادُونَ', 'فمن ٱبتغي وراء ذلك فاو۟ليك هم ٱلعادون'),
('s70a32', 32, 70, 'وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', 'وٱلذين هم لامنتهم وعهدهم رعون'),
('s70a33', 33, 70, 'وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمْ قَآئِمُونَ', 'وٱلذين هم بشهدتهم قايمون'),
('s70a34', 34, 70, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 'وٱلذين هم علي صلاتهم يحافظون'),
('s70a35', 35, 70, 'أُو۟لَٰٓئِكَ فِى جَنَّٰتٍۢ مُّكْرَمُونَ', 'او۟ليك في جنتۢ مكرمون'),
('s70a36', 36, 70, 'فَمَالِ ٱلَّذِينَ كَفَرُوا۟ قِبَلَكَ مُهْطِعِينَ', 'فمال ٱلذين كفروا۟ قبلك مهطعين'),
('s70a37', 37, 70, 'عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ', 'عن ٱليمين وعن ٱلشمال عزين'),
('s70a38', 38, 70, 'أَيَطْمَعُ كُلُّ ٱمْرِئٍۢ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍۢ', 'ايطمع كل ٱمريۢ منهم ان يدخل جنه نعيمۢ'),
('s70a39', 39, 70, 'كَلَّآ ۖ إِنَّا خَلَقْنَٰهُم مِّمَّا يَعْلَمُونَ', 'كلا ۖ انا خلقنهم مما يعلمون'),
('s70a40', 40, 70, 'فَلَآ أُقْسِمُ بِرَبِّ ٱلْمَشَٰرِقِ وَٱلْمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ', 'فلا اقسم برب ٱلمشرق وٱلمغرب انا لقدرون'),
('s70a41', 41, 70, 'عَلَىٰٓ أَن نُّبَدِّلَ خَيْرًۭا مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ', 'علي ان نبدل خيرۭا منهم وما نحن بمسبوقين'),
('s70a42', 42, 70, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', 'فذرهم يخوضوا۟ ويلعبوا۟ حتي يلقوا۟ يومهم ٱلذي يوعدون'),
('s70a43', 43, 70, 'يَوْمَ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ سِرَاعًۭا كَأَنَّهُمْ إِلَىٰ نُصُبٍۢ يُوفِضُونَ', 'يوم يخرجون من ٱلاجداث سراعۭا كانهم الي نصبۢ يوفضون'),
('s70a44', 44, 70, 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌۭ ۚ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 'خشعه ابصرهم ترهقهم ذلهۭ ۚ ذلك ٱليوم ٱلذي كانوا۟ يوعدون')
